#!/usr/bin/env python3
"""Regenerates the generated parts of rc4's LAWS.bend, PROOF.bend and check.bend.

  python3 gen/vectors.py           rewrite the regions between the lines
                                   "# BEGIN GENERATED by gen/vectors.py: <name>"
                                   and "# END GENERATED: <name>"
  python3 gen/vectors.py --check   only check that they are up to date

Three regions: "vectors" in LAWS.bend, the vector laws (the
specification's test values and the refusals, as {==} claims);
"vectors" in PROOF.bend, one {==} proof per vector law; and "check" in
check.bend, its main and the expected #| lines.
The expected values come from ref/model.py, the package's independent
model, which ref/gen.py checks against the specification's published
vectors. Everything outside the regions is written by hand.
"""
import os, re, sys

HERE = os.path.dirname(os.path.abspath(__file__))
PKG = os.path.join(HERE, "..")
sys.dont_write_bytecode = True
sys.path.insert(0, os.path.join(PKG, "ref"))
import model as m

h = bytes.fromhex


def lst(b):
    return "B.Octets.of_list([" + ", ".join(str(x) for x in b) + "])"


def blk128(b):
    return "M.CmBlock{%s}" % ", ".join(str(int.from_bytes(b[4 * i:4 * i + 4], "big")) for i in range(4))


def blk64(b):
    return "L.LcBlock64{%d, %d}" % (int.from_bytes(b[:4], "big"), int.from_bytes(b[4:], "big"))


def cbc(enc, key, iv, data, bs):
    out, prev = b"", iv
    for i in range(0, len(data), bs):
        prev = enc(key, bytes(a ^ b for a, b in zip(data[i:i + bs], prev)))
        out += prev
    return out


# ---------------------------------------------------------------- LAWS.bend

def vectors_region():
    out = []

    def law(name, comment, body):
        out.append("# %s\nlaw %s:\n  %s\n" % (comment, name, body))

    def v128(name, comment, mod, key_t, keyfn, key, pt, ct):
        law(name, comment, "{Result.map(&2, &2, L.LcError, %s, M.CmBlock, k => %s.encrypt(k, %s), %s(%s)) == Done{%s} : Result<&2, &2, L.LcError, M.CmBlock>}" % (key_t, mod, blk128(pt), keyfn, lst(key), blk128(ct)))

    def v64(name, comment, mod, key_t, keyfn, key, pt, ct):
        law(name, comment, "{Result.map(&2, &2, L.LcError, %s, L.LcBlock64, k => %s.encrypt(k, %s), %s(%s)) == Done{%s} : Result<&2, &2, L.LcError, L.LcBlock64>}" % (key_t, mod, blk64(pt), keyfn, lst(key), blk64(ct)))

    def refusal(name, comment, key_t, keyfn, n):
        law(name, comment, "{Result.map(&2, &2, L.LcError, %s, Unit, k => Unit{}, %s(%s)) == Fail{L.LcBadKeyLength{%dn}} : Result<&2, &2, L.LcError, Unit>}" % (key_t, keyfn, lst(bytes(n)), n))

    law("rc4_empty_key", "an empty RC4 key is refused", "{R.LcRc4.crypt(B.Octets.empty(), B.Octets.zeros(4n)) == Fail{L.LcBadKeyLength{0n}} : Result<&2, &2, L.LcError, B.Octets>}")
    return "\n".join(out) + "\n"


# ---------------------------------------------------------------- PROOF.bend

def proof_region():
    """one {==} proof per vector law"""
    laws = open(os.path.join(PKG, "LAWS.bend"), encoding="utf-8").read()
    start = laws.index("# BEGIN GENERATED by gen/vectors.py: vectors")
    names = re.findall(r"^law (\w+):", laws[start:], re.M)
    return "".join("\ndef Laws.%s():\n  {==}\n" % n for n in names)


# ---------------------------------------------------------------- check.bend

def check_region():
    lines, expect = [], []

    def out(expr, value):
        lines.append("    IO.print(%s)" % expr)
        expect.append(value)

    # RFC 6229, the 40-bit key 0102030405, every offset it lists
    ks = m.rc4_keystream(h("0102030405"), 4112)
    for o in [0, 16, 240, 256, 496, 512, 752, 768, 1008, 1024, 1520, 1536, 2032, 2048, 3056, 3072, 4080, 4096]:
        out("B.Octets.hex(B.Octets.slice(%dn, 16n, rc4_ks(%s, 4112n)))" % (o, lst(h("0102030405"))), ks[o:o + 16].hex())
    # RC4 in pieces, and RC4-drop[1536] (RFC 4345)
    out("rc4_pieces(%s)" % lst(h("0102030405")), m.rc4_keystream(h("0102030405"), 48).hex())
    out("rc4_drop(%s)" % lst(h("0102030405")), m.rc4_keystream(h("0102030405"), 16, 1536).hex())
    return "def main() -> IO(Unit):\n  do IO<Unit>:\n" + "\n".join(lines) + "\n\n" + "\n".join("#|" + e for e in expect) + "\n"


REGIONS = [("LAWS.bend", "vectors", vectors_region), ("PROOF.bend", "vectors", proof_region),
           ("check.bend", "check", check_region)]


def main():
    check = "--check" in sys.argv[1:]
    stale = False
    for fname, name, body in REGIONS:
        path = os.path.join(PKG, fname)
        with open(path, encoding="utf-8", newline="") as f:
            src = f.read()
        begin = "# BEGIN GENERATED by gen/vectors.py: %s\n" % name
        end = "# END GENERATED: %s\n" % name
        i = src.index(begin) + len(begin)
        j = src.index(end, i)
        new = src[:i] + body() + src[j:]
        if check:
            if new != src:
                print("%s differs from what gen/vectors.py generates" % fname)
                stale = True
            continue
        with open(path, "w", encoding="utf-8", newline="\n") as f:
            f.write(new)
    if check:
        if stale:
            sys.exit(1)
        print("LAWS.bend, PROOF.bend and check.bend are up to date")


main()
